<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CMS Konten | Magang Komdigi 2026</title>
<script src="https://cdn.tailwindcss.com"></script>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<script>tailwind.config={theme:{extend:{colors:{'komdigi-blue':'#0055FF','komdigi-dark':'#00336C','komdigi-cerulean':'#0093DD','komdigi-navy':'#001B3D'},fontFamily:{sans:['Inter','sans-serif']}}}}</script>
<style>
body{overflow-x:hidden;background:linear-gradient(160deg,#001B3D 0%,#00336C 28%,#0055FF 65%,#0093DD 100%);background-attachment:fixed;min-height:100vh}
body::before{content:'';position:fixed;inset:0;background:radial-gradient(ellipse 90% 60% at 10% 20%,rgba(0,147,221,.35) 0%,transparent 55%),radial-gradient(ellipse 70% 50% at 90% 10%,rgba(0,85,255,.3) 0%,transparent 50%),radial-gradient(ellipse 60% 40% at 50% 90%,rgba(0,51,108,.4) 0%,transparent 50%);pointer-events:none;z-index:0}
.glass-strong{background:rgba(15,23,42,.38);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);border:1px solid rgba(255,255,255,.12);box-shadow:0 8px 32px rgba(0,0,0,.2)}
.glass-card{background:rgba(15,23,42,.26);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border:1px solid rgba(125,211,252,.45);box-shadow:0 0 0 1px rgba(255,255,255,.14),0 0 14px rgba(56,189,248,.4),0 0 32px rgba(0,147,221,.32),0 6px 24px rgba(0,0,0,.16),inset 0 1px 1px rgba(255,255,255,.2);color:#e2e8f0}
.glass-panel{background:rgba(8,12,24,.35);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);border:1px solid rgba(125,211,252,.28);box-shadow:0 0 0 1px rgba(255,255,255,.08),0 0 24px rgba(0,147,221,.22),0 12px 48px rgba(0,0,0,.2),inset 0 1px 0 rgba(255,255,255,.12);border-radius:1.5rem}
.glass-sidebar{background:rgba(8,12,24,.35);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);border:1px solid rgba(255,255,255,.1);width:68px;transition:width .28s;overflow:hidden;z-index:40}
.glass-sidebar::-webkit-scrollbar{display:none}.glass-sidebar{scrollbar-width:none}
.glass-sidebar:hover{width:240px;background:rgba(8,12,24,.5)}
.glass-sidebar .sidebar-label{opacity:0;white-space:nowrap;transition:opacity .18s;pointer-events:none;font-size:.8125rem}
.glass-sidebar:hover .sidebar-label{opacity:1;pointer-events:auto}
.glass-sidebar .sidebar-section-title{opacity:0;max-height:0;margin:0;padding:0;overflow:hidden;transition:all .2s}
.glass-sidebar:hover .sidebar-section-title{opacity:1;max-height:2rem;margin-bottom:.75rem;padding:0 .5rem}
.sidebar-link{transition:all .2s;color:rgba(186,198,214,.95);font-weight:500;display:flex;align-items:center;gap:.7rem;padding:.55rem .7rem;border-radius:.7rem;position:relative;margin:0 .2rem}
.sidebar-link:hover{background:rgba(255,255,255,.07);color:#f8fafc}
.sidebar-link.active{background:rgba(0,147,221,.18);color:#fff;font-weight:600}
.sidebar-link.active::before{content:'';position:absolute;left:0;top:50%;transform:translateY(-50%);width:3px;height:55%;background:#38bdf8;border-radius:0 3px 3px 0}
.sidebar-link .sidebar-icon{width:1.85rem;height:1.85rem;border-radius:.5rem;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:rgba(255,255,255,.05)}
.sidebar-link.active .sidebar-icon{background:rgba(0,147,221,.3)}
.btn-shine{position:relative;overflow:hidden}
.btn-shine::after{content:'';position:absolute;top:0;left:-100%;width:60%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);transition:.5s}
.btn-shine:hover::after{left:120%}
.form-input{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);color:#f1f5f9;border-radius:.75rem;padding:.6rem .9rem;width:100%;font-size:.875rem}
.form-input:focus{outline:none;border-color:rgba(56,189,248,.5);box-shadow:0 0 0 3px rgba(56,189,248,.15)}
.form-input::placeholder{color:#64748b}select.form-input option{background:#0f172a;color:#f1f5f9}
textarea.form-input{min-height:90px;resize:vertical}
.modal-overlay{background:rgba(0,0,0,.6);backdrop-filter:blur(6px)}
.tab-btn{white-space:nowrap}.tab-btn.active{background:rgba(0,147,221,.25);color:#fff;border-color:rgba(56,189,248,.4)}
.status-badge{display:inline-flex;align-items:center;gap:.3rem;padding:.2rem .6rem;border-radius:9999px;font-size:.7rem;font-weight:600}
.status-publish,.status-aktif{background:rgba(16,185,129,.2);color:#34d399;border:1px solid rgba(16,185,129,.3)}
.status-draft,.status-nonaktif{background:rgba(148,163,184,.2);color:#94a3b8;border:1px solid rgba(148,163,184,.3)}
.kategori-badge{display:inline-flex;padding:.15rem .5rem;border-radius:.4rem;font-size:.65rem;font-weight:600}
.kat-pribadi{background:rgba(139,92,246,.2);color:#a78bfa}.kat-semua{background:rgba(14,165,233,.2);color:#38bdf8}
.kat-tim{background:rgba(245,158,11,.2);color:#fbbf24}.kat-peserta{background:rgba(14,165,233,.2);color:#38bdf8}
.kat-pembimbing{background:rgba(139,92,246,.2);color:#a78bfa}.kat-koordinator{background:rgba(245,158,11,.2);color:#fbbf24}
.kat-hero{background:rgba(236,72,153,.2);color:#f472b6}.kat-popup{background:rgba(245,158,11,.2);color:#fbbf24}
.kat-running{background:rgba(14,165,233,.2);color:#38bdf8}
.tabs-scroll{display:flex;gap:.5rem;overflow-x:auto;padding-bottom:.25rem;scrollbar-width:thin}
.rich-editor{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:.75rem;min-height:140px;padding:.75rem;color:#f1f5f9;font-size:.875rem}
.rich-toolbar{display:flex;flex-wrap:wrap;gap:.25rem;margin-bottom:.5rem}
.rich-toolbar button{padding:.35rem .6rem;border-radius:.4rem;background:rgba(255,255,255,.08);color:#cbd5e1;font-size:.75rem;font-weight:600;border:1px solid rgba(255,255,255,.1)}
.dropzone{border:2px dashed rgba(125,211,252,.35);background:rgba(14,165,233,.06);border-radius:1rem;padding:1.25rem;text-align:center}
.avatar-lg{width:72px;height:72px;border-radius:1rem;background:linear-gradient(135deg,#0055FF,#0093DD);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;font-size:1.25rem}
.drag-handle{cursor:grab;color:#64748b}
</style>
</head>
<body class="font-sans antialiased">
<header class="sticky top-0 z-50 pt-4 px-4 sm:px-5 relative">
<div class="w-full"><div class="flex items-center justify-between gap-3 px-4 py-3 glass-strong rounded-2xl">
<div class="flex items-center gap-3 shrink-0">
<div class="relative"><div class="absolute inset-0 bg-komdigi-blue rounded-xl blur-md opacity-40"></div>
<div class="relative w-10 h-10 bg-gradient-to-br from-komdigi-blue to-komdigi-cerulean rounded-xl flex items-center justify-center text-white font-black text-sm shadow-lg">K</div></div>
<div class="hidden sm:block"><div class="font-extrabold text-white text-sm leading-tight tracking-tight">MAGANG KOMDIGI</div><div class="text-[10px] font-semibold text-komdigi-cerulean">Admin Panel · 2026</div></div>
</div>
<div class="flex items-center gap-3 shrink-0">
<div class="hidden sm:flex items-center gap-2.5">
<div class="w-9 h-9 rounded-full bg-gradient-to-br from-amber-500 to-orange-500 flex items-center justify-center text-white text-xs font-bold ring-2 ring-white/30 shadow-md">AD</div>
<div class="hidden md:block"><div class="text-xs font-bold text-white leading-tight">Admin Komdigi</div><div class="text-[10px] text-emerald-400 font-medium">● Online</div></div>
</div>
<a href="#" class="inline-flex items-center px-4 py-2 text-sm font-bold text-white bg-gradient-to-r from-komdigi-dark to-komdigi-blue rounded-full shadow-md">Keluar</a>
</div></div></div>
</header>

<div class="flex min-h-[calc(100vh-88px)] relative z-10 pl-0 lg:pl-3 gap-0 lg:gap-3">
<aside class="hidden lg:flex flex-col glass-sidebar shrink-0 sticky top-[88px] h-[calc(100vh-100px)] mt-2 mb-3 rounded-2xl">
<div class="py-4 px-2 flex-1 overflow-y-auto overflow-x-hidden">
<p class="sidebar-section-title text-[10px] font-bold tracking-widest text-blue-300/60 uppercase">Admin Menu</p>
<nav class="space-y-0.5">
