<main class="flex-1 p-3 sm:p-4 lg:p-5 overflow-y-auto">
<div class="glass-panel p-5 sm:p-6 lg:p-8 space-y-6 min-h-[calc(100vh-120px)]">
<div>
<h1 class="text-2xl sm:text-3xl font-black text-white tracking-tight">CMS / Konten Publik</h1>
<p class="text-sm text-blue-100/80 mt-0.5">Kelola seluruh konten landing page & area publik Magang Komdigi</p>
</div>

<div class="tabs-scroll">
<button onclick="switchTab('kegiatan')" id="tab-kegiatan" class="tab-btn active px-3.5 py-2 text-xs sm:text-sm font-semibold rounded-xl border border-white/10">Kegiatan</button>
<button onclick="switchTab('dokumentasi')" id="tab-dokumentasi" class="tab-btn px-3.5 py-2 text-xs sm:text-sm font-semibold rounded-xl border border-white/10 text-slate-400 hover:text-white">Dokumentasi</button>
<button onclick="switchTab('anggota')" id="tab-anggota" class="tab-btn px-3.5 py-2 text-xs sm:text-sm font-semibold rounded-xl border border-white/10 text-slate-400 hover:text-white">Profil / Anggota</button>
<button onclick="switchTab('halaman')" id="tab-halaman" class="tab-btn px-3.5 py-2 text-xs sm:text-sm font-semibold rounded-xl border border-white/10 text-slate-400 hover:text-white">Halaman Statis</button>
<button onclick="switchTab('pengumuman')" id="tab-pengumuman" class="tab-btn px-3.5 py-2 text-xs sm:text-sm font-semibold rounded-xl border border-white/10 text-slate-400 hover:text-white">Pengumuman</button>
<button onclick="switchTab('hero')" id="tab-hero" class="tab-btn px-3.5 py-2 text-xs sm:text-sm font-semibold rounded-xl border border-white/10 text-slate-400 hover:text-white">Hero & Countdown</button>
<button onclick="switchTab('menu')" id="tab-menu" class="tab-btn px-3.5 py-2 text-xs sm:text-sm font-semibold rounded-xl border border-white/10 text-slate-400 hover:text-white">Menu Navigasi</button>
<button onclick="switchTab('dokumen')" id="tab-dokumen" class="tab-btn px-3.5 py-2 text-xs sm:text-sm font-semibold rounded-xl border border-white/10 text-slate-400 hover:text-white">Dokumen</button>
<button onclick="switchTab('faq')" id="tab-faq" class="tab-btn px-3.5 py-2 text-xs sm:text-sm font-semibold rounded-xl border border-white/10 text-slate-400 hover:text-white">FAQ</button>
</div>

<!-- KEGIATAN -->
<div id="panel-kegiatan" class="space-y-5">
<div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
<div><h2 class="text-lg font-bold text-white">Logbook Kegiatan Publik</h2><p class="text-xs text-slate-400">Section “Kegiatan Terbaru”</p></div>
<button class="btn-shine inline-flex items-center gap-2 px-4 py-2.5 bg-gradient-to-r from-komdigi-blue to-komdigi-cerulean text-white text-sm font-bold rounded-xl shadow-md" onclick="alert('Modal Tambah Kegiatan')"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>Tambah Kegiatan</button>
</div>
<div class="grid grid-cols-2 sm:grid-cols-4 gap-3">
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Total</p><p class="text-2xl font-black text-white mt-1">6</p></div>
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Published</p><p class="text-2xl font-black text-emerald-400 mt-1">4</p></div>
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Draft</p><p class="text-2xl font-black text-slate-300 mt-1">2</p></div>
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Pinned</p><p class="text-2xl font-black text-amber-400 mt-1">1</p></div>
</div>
<div class="glass-card rounded-2xl p-6 text-sm text-slate-300">Fitur Kegiatan (judul, deskripsi, tanggal, kategori Pribadi/Semua/Tim, cover, status Draft/Publish, pin, filter & search) sudah tersedia. Gunakan untuk mengelola section Kegiatan Terbaru.</div>
</div>

<!-- DOKUMENTASI -->
<div id="panel-dokumentasi" class="hidden space-y-5">
<div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
<div><h2 class="text-lg font-bold text-white">Galeri Dokumentasi</h2><p class="text-xs text-slate-400">Section “Dokumentasi”</p></div>
<button class="btn-shine inline-flex items-center gap-2 px-4 py-2.5 bg-gradient-to-r from-komdigi-blue to-komdigi-cerulean text-white text-sm font-bold rounded-xl shadow-md" onclick="alert('Modal Upload Multiple Foto')"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>Upload Foto</button>
</div>
<div class="grid grid-cols-2 sm:grid-cols-4 gap-3">
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Total Foto</p><p class="text-2xl font-black text-white mt-1">12</p></div>
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Published</p><p class="text-2xl font-black text-emerald-400 mt-1">9</p></div>
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Unpublished</p><p class="text-2xl font-black text-slate-300 mt-1">3</p></div>
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Kategori</p><p class="text-2xl font-black text-komdigi-cerulean mt-1">4</p></div>
</div>
<div class="glass-card rounded-2xl p-6 text-sm text-slate-300">Fitur Galeri: upload multiple, caption, kategori, tanggal, urutan, publish/unpublish, hapus foto. Sudah diimplementasikan di versi sebelumnya.</div>
</div>

<!-- ANGGOTA -->
<div id="panel-anggota" class="hidden space-y-5">
<div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
<div><h2 class="text-lg font-bold text-white">Profil Tim & Anggota</h2><p class="text-xs text-slate-400">Section Profil Tim dan daftar anggota</p></div>
<button onclick="openModal('modalAnggota')" class="btn-shine inline-flex items-center gap-2 px-4 py-2.5 bg-gradient-to-r from-komdigi-blue to-komdigi-cerulean text-white text-sm font-bold rounded-xl shadow-md"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>Tambah Anggota</button>
</div>
<div class="grid grid-cols-2 sm:grid-cols-4 gap-3">
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Total</p><p class="text-2xl font-black text-white mt-1">8</p></div>
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Peserta</p><p class="text-2xl font-black text-sky-400 mt-1">5</p></div>
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Pembimbing</p><p class="text-2xl font-black text-violet-400 mt-1">2</p></div>
<div class="glass-card rounded-xl p-4"><p class="text-[11px] font-semibold text-slate-400 uppercase">Aktif</p><p class="text-2xl font-black text-emerald-400 mt-1">7</p></div>
</div>
<div class="glass-card rounded-2xl p-4"><div class="grid sm:grid-cols-3 gap-3">
<input type="text" placeholder="Cari nama..." class="form-input" oninput="filterTable('anggotaBody',this.value)">
<select class="form-input" onchange="filterPosisi(this.value)"><option value="">Semua Posisi</option><option value="peserta">Peserta</option><option value="pembimbing">Pembimbing</option><option value="koordinator">Koordinator</option></select>
<select class="form-input"><option value="">Semua Status</option><option>Aktif</option><option>Nonaktif</option></select>
</div></div>
<div class="glass-card rounded-2xl overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-sm">
