<div id="modalDokumen" class="fixed inset-0 z-[100] hidden items-center justify-center p-4"><div class="absolute inset-0 modal-overlay" onclick="closeModal('modalDokumen')"></div><div class="relative glass-strong rounded-3xl shadow-2xl w-full max-w-lg border border-white/15 max-h-[90vh] overflow-y-auto"><div class="p-6">
<div class="flex items-center justify-between mb-5"><h3 class="text-lg font-black text-white">Upload / Edit Dokumen</h3><button onclick="closeModal('modalDokumen')" class="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center"><svg class="w-4 h-4 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg></button></div>
<div class="space-y-4">
<div><label class="block text-xs font-semibold text-slate-400 mb-1.5">Nama Tampilan *</label><input type="text" class="form-input" placeholder="Panduan Magang 2026"></div>
<div><label class="block text-xs font-semibold text-slate-400 mb-1.5">File</label><div class="dropzone"><p class="text-sm text-slate-300">Klik atau drag file di sini</p><p class="text-[11px] text-slate-500 mt-1">PDF, DOC, DOCX, XLS, XLSX · Maks. 10 MB</p></div></div>
<div class="grid grid-cols-2 gap-3"><div><label class="block text-xs font-semibold text-slate-400 mb-1.5">Kategori</label><select class="form-input"><option>Panduan</option><option>Template</option><option>Form</option><option>Lainnya</option></select></div><div><label class="block text-xs font-semibold text-slate-400 mb-1.5">Akses Download</label><select class="form-input"><option>Publik</option><option>Login saja</option></select></div></div>
</div>
<div class="flex gap-3 mt-6"><button onclick="closeModal('modalDokumen')" class="flex-1 py-3 bg-white/10 text-slate-300 font-bold rounded-xl text-sm border border-white/10">Batal</button><button onclick="closeModal('modalDokumen');alert('Dokumen berhasil di-upload!')" class="btn-shine flex-1 py-3 bg-gradient-to-r from-komdigi-blue to-komdigi-cerulean text-white font-bold rounded-xl text-sm">Simpan</button></div>
</div></div></div>

<div id="modalFaq" class="fixed inset-0 z-[100] hidden items-center justify-center p-4"><div class="absolute inset-0 modal-overlay" onclick="closeModal('modalFaq')"></div><div class="relative glass-strong rounded-3xl shadow-2xl w-full max-w-lg border border-white/15 max-h-[90vh] overflow-y-auto"><div class="p-6">
<div class="flex items-center justify-between mb-5"><h3 class="text-lg font-black text-white">Tambah / Edit FAQ</h3><button onclick="closeModal('modalFaq')" class="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center"><svg class="w-4 h-4 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg></button></div>
<div class="space-y-4">
<div><label class="block text-xs font-semibold text-slate-400 mb-1.5">Pertanyaan *</label><input type="text" class="form-input" placeholder="Siapa yang boleh mendaftar?"></div>
<div><label class="block text-xs font-semibold text-slate-400 mb-1.5">Jawaban *</label><textarea class="form-input" placeholder="Jawaban lengkap..."></textarea></div>
<div class="grid grid-cols-2 gap-3"><div><label class="block text-xs font-semibold text-slate-400 mb-1.5">Kategori FAQ</label><select class="form-input"><option>Umum</option><option>Teknis</option><option>Administrasi</option><option>Lainnya</option></select></div><div><label class="block text-xs font-semibold text-slate-400 mb-1.5">Urutan</label><input type="number" class="form-input" min="1" value="1"></div></div>
</div>
<div class="flex gap-3 mt-6"><button onclick="closeModal('modalFaq')" class="flex-1 py-3 bg-white/10 text-slate-300 font-bold rounded-xl text-sm border border-white/10">Batal</button><button onclick="closeModal('modalFaq');alert('FAQ berhasil disimpan!')" class="btn-shine flex-1 py-3 bg-gradient-to-r from-komdigi-blue to-komdigi-cerulean text-white font-bold rounded-xl text-sm">Simpan</button></div>
</div></div></div>

<div id="modalDelete" class="fixed inset-0 z-[100] hidden items-center justify-center p-4"><div class="absolute inset-0 modal-overlay" onclick="closeModal('modalDelete')"></div><div class="relative glass-strong rounded-3xl shadow-2xl w-full max-w-sm border border-white/15"><div class="p-6 text-center">
<div class="w-14 h-14 rounded-2xl bg-rose-500/20 flex items-center justify-center mx-auto mb-4"><svg class="w-7 h-7 text-rose-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></div>
<h3 class="text-lg font-black text-white mb-1">Hapus Item?</h3>
<p class="text-sm text-slate-400 mb-5">Item yang dihapus tidak dapat dikembalikan.</p>
<div class="flex gap-3"><button onclick="closeModal('modalDelete')" class="flex-1 py-3 bg-white/10 text-slate-300 font-bold rounded-xl text-sm border border-white/10">Batal</button><button onclick="closeModal('modalDelete');alert('Item berhasil dihapus.')" class="flex-1 py-3 bg-gradient-to-r from-rose-500 to-rose-600 text-white font-bold rounded-xl text-sm">Ya, Hapus</button></div>
</div></div></div>

<script>
const tabs=['kegiatan','dokumentasi','anggota','halaman','pengumuman','hero','menu','dokumen','faq'];
function switchTab(tab){tabs.forEach(t=>{const p=document.getElementById('panel-'+t),b=document.getElementById('tab-'+t);if(p)p.classList.add('hidden');if(b){b.classList.remove('active');b.classList.add('text-slate-400')}});const p=document.getElementById('panel-'+tab),b=document.getElementById('tab-'+tab);if(p)p.classList.remove('hidden');if(b){b.classList.add('active');b.classList.remove('text-slate-400')}}
function openModal(id){document.getElementById(id).classList.remove('hidden');document.getElementById(id).classList.add('flex')}
function closeModal(id){document.getElementById(id).classList.add('hidden');document.getElementById(id).classList.remove('flex')}
function filterTable(id,q){q=(q||'').toLowerCase();document.querySelectorAll('#'+id+' tr').forEach(tr=>{tr.style.display=!q||tr.textContent.toLowerCase().includes(q)?'':'none'})}
function filterPosisi(v){document.querySelectorAll('#anggotaBody tr').forEach(tr=>{tr.style.display=!v||tr.dataset.posisi===v?'':'none'})}
</script>
</body>
</html>